const helpers = this.helpers;
const baseUrl = 'https://suporte.araraquara.sp.gov.br/api.php/v1';
const appToken = $('Carregar Tokens').first().json.app_token;
const userToken = $('Carregar Tokens').first().json.user_token;
const I_FORM = 'Glpi%5CForm%5CForm';
const I_DEST = 'Glpi%5CForm%5CDestination%5CFormDestination';

const MAPA = {
  'Criacao de Usuario': 15, 'Reset de Senha': 16, 'Reativacao de Usuario': 17,
  'Desativacao de Usuario': 18, 'Acesso a Pasta de Rede': 19,
  'Criacao de E-mail Institucional': 20, 'Transferencia de Setor ou Local': 22,
  'Manutencao de Impressoras': 23, 'Manutencao de Computador': 24,
  'Instalacao de Software': 25, 'Atualizacao de Software': 26,
  'Reparacao de Software': 27, 'Internet Lenta ou Instavel': 28,
  'Sem Conexao com a Internet': 29, 'Acesso Wi-Fi': 30,
  'VPN / Acesso Remoto': 31, 'Outros Assuntos de Rede': 32, 'Cartucho ou Toner': 33,
  'Saude - Problemas de Acesso': 34, 'Saude - Novo Acesso': 35, 'Saude - Solicitacoes Gerais': 36,
  'Telefonia - Problemas com Ramal': 37, 'Telefonia - Aparelho Telefonico': 38,
  'Telefonia - Celular e Chip': 39, 'Telefonia - Outros': 40
};

async function callRaw(method, url, headers) {
  const resp = await helpers.httpRequest({ method, url, headers, json: false, returnFullResponse: true, ignoreHttpStatusErrors: true });
  let parsed = resp.body;
  if (typeof parsed === 'string') { try { parsed = JSON.parse(parsed); } catch(_) {} }
  return { status: resp.statusCode || resp.status, body: parsed };
}

const r0 = await callRaw('GET', `${baseUrl}/initSession`, {
  'App-Token': appToken, 'Authorization': `user_token ${userToken}`
});
if (r0.status !== 200) return [{ json: { erro: 'auth falhou', detalhe: r0.body } }];
const H = { 'App-Token': appToken, 'Session-Token': r0.body.session_token };

const formsRes = await callRaw('GET', `${baseUrl}/${I_FORM}?range=0-200`, H);
const formsArr = Array.isArray(formsRes.body) ? formsRes.body : (formsRes.body.data || []);
const formIdToName = {};
for (const f of formsArr) {
  if (f && f.is_deleted === 0 && MAPA[f.name] !== undefined) formIdToName[f.id] = f.name;
}

const destsRes = await callRaw('GET', `${baseUrl}/${I_DEST}?range=0-500`, H);
const destsArr = Array.isArray(destsRes.body) ? destsRes.body : (destsRes.body.data || []);

const itens = [];
for (const d of destsArr) {
  if (!d || !formIdToName[d.forms_forms_id]) continue;
  const formName = formIdToName[d.forms_forms_id];
  const esperada = MAPA[formName];
  let cfg = null;
  try { cfg = typeof d.config === 'string' ? JSON.parse(d.config) : d.config; } catch(_) {}
  const catField = cfg ? cfg['glpi-form-destination-commonitilfield-itilcategoryfield'] : null;
  const catSetada = catField ? catField.specific_itilcategories_id : null;
  const strategy = catField ? catField.strategy : null;
  itens.push({
    form_name: formName, form_id: d.forms_forms_id,
    dest_id: d.id, dest_name: d.name,
    categoria_esperada: esperada,
    categoria_setada: catSetada,
    bate: (catSetada === esperada),
    strategy_categoria: strategy,
    chaves_do_config: cfg ? Object.keys(cfg) : [],
    itilcategoryfield: catField
  });
}

await callRaw('GET', `${baseUrl}/killSession`, H);

const oks = itens.filter(o => o.bate).length;
const erros = itens.filter(o => !o.bate);
const resumo = {
  __resumo: true,
  total_destinations: itens.length,
  com_categoria_ok: oks,
  com_problema: erros.length,
  problemas: erros.map(o => `${o.form_name} (dest_id ${o.dest_id}): esperado=${o.categoria_esperada} setado=${o.categoria_setada} strategy=${o.strategy_categoria}`)
};

return [{ json: resumo }, ...itens.map(o => ({ json: o }))];

